using System.Net;using System.Net.Mail;
namespace BusinessPartnerPortal.Api.Services;
public sealed class EmailOtpSender(IConfiguration config,ILogger<EmailOtpSender> logger){public async Task SendAsync(string email,string otp,CancellationToken ct){if(!bool.TryParse(config["SMTP_ENABLED"],out var enabled)||!enabled){logger.LogWarning("SMTP is disabled. Development OTP generated for {Email}.",email);return;}var host=config["SMTP_HOST"]??throw new InvalidOperationException("SMTP_HOST is required.");var port=int.TryParse(config["SMTP_PORT"],out var p)?p:587;using var client=new SmtpClient(host,port){EnableSsl=true,Credentials=new NetworkCredential(config["SMTP_USERNAME"],config["SMTP_PASSWORD"])};using var msg=new MailMessage(config["SMTP_FROM"]??config["SMTP_USERNAME"]!,email,"Pakistan Cables Portal Verification",$"Your Business Partner's Portal OTP is {otp}. It expires in 10 minutes.");await client.SendMailAsync(msg,ct);}}
